import{_ as e,o as t,c as r,a5 as o}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"自動化を整理する","description":"","frontmatter":{"title":"自動化を整理する","docId":"user.automations.index","translationKey":"user.automations.index","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","translationRevision":"27453dca716ff3eafbc81c5357a110b15a3d0344690b36b5a07dbf7d4030fc57","order":10},"headers":[],"relativePath":"ja/user/automations/index.md","filePath":"ja/user/automations/index.md","lastUpdated":1794611623000}'),i={name:"ja/user/automations/index.md"};function n(s,a,l,d,u,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="organize-automations" tabindex="-1">自動化を整理する <a class="header-anchor" href="#organize-automations" aria-label="Permalink to &quot;自動化を整理する {#organize-automations}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>LIVE のイベントに反応する、小さく分かりやすいライブラリを作ります。正常に動くデスクトップホストが必要です。配信元のイベントの検証には実際の <a href="./../live/connections.html">LIVE 接続</a> が、プラグインのアクションには対応するプラグインとサービスの準備も必要です。</p><h2 id="understand-the-library" tabindex="-1">ライブラリの仕組み <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to &quot;ライブラリの仕組み {#understand-the-library}&quot;">​</a></h2><p><strong>アクション</strong> はログ出力や音の再生など、設定を再利用できる処理です。<strong>イベント</strong> はトリガー、フィルター、クールダウン、関連アクションを指定します。プロファイルは用途ごとに定義をまとめ、一度に有効になるプロファイルパックは1つです。実行時の<a href="./variables.html">変数</a> を使うと、複数のアクションで値を共有できます。</p><ol><li><strong>自動化</strong> を開き、編集前にアクティブなプロファイルを確認します。イベントとアクションは別々に検索し、選ぶレコードの種類を把握します。</li><li><a href="./first-rule.html">最初のログ記録ルール</a> から始めます。先にアクションを作り、それを参照するイベントを作成します。</li><li>現在のホストが対応するトリガーを選び、フィールド選択から対応するフィルターを追加します。複数条件は一致範囲を絞りますが、受信ペイロードは変更しません。</li><li>クールダウンと適用範囲を設定します。全体のクールダウンは全視聴者を通じてルールを制限し、ユーザー別では視聴者ごとに管理します。</li><li>目的のアクションを順に関連付けます。通常モードは選んだ一覧を実行し、ランダムモードはその中から1つ選びます。遅延アクションは後続処理を遅らせますが、LIVE の取り込みは遅らせません。</li><li>保存して表示された定義の変更を確認し、実行するレコードを明示的に有効にします。履歴でアクション名、結果、エラーを確認します。</li></ol><p>テストでも設定した処理が実行されます。特に音声、HTTP、ポイント、プラグインでは、<strong>テストを実行</strong> やイベント実行の前に選択中のアクション一覧を読んでください。学習中はログを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>ローカル編集、実行、テンプレート、プロファイル、履歴を利用できます。プラグインのトリガーは対応プラグインがインストールされ有効な間だけ表示されます。有効状態はインポート経路と確認済み enabled 値によります。確定前にイベントとアクションを確認してください。イベント／アクションの <strong>変更</strong> は<a href="./../cloud/changes.html">ローカルの基準との比較</a> であり、Cloud への自動アップロードではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>実行されない場合は、アクティブなプロファイル、有効状態、トリガー、フィルター、クールダウン、欠けたアクションの順に確認します。リビジョンが競合したら、現在の保存済み定義を読み直して再確認します。他の人の更新を無条件に上書きしないでください。大きな変更の前に、正常な<a href="./templates.html">プロファイル</a> をエクスポートします。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>取り込み・切り替え前に<a href="./templates.html#operational-details">経路ごとの有効化規則</a>を読みます。個別に無効化した項目も再び有効になる場合があります。cooldown はメモリ内で最大 24 時間、uniqueId 不在の視聴者は匿名範囲を共有します。保持キー 8,192 件で表を空にするため、過負荷や再起動で追加実行が起こり得ます。永続 quota・replay 保証ではありません。</p>',13)])])}const m=e(i,[["render",n]]);export{p as __pageData,m as default};
